package com.bank.branch.service;

import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the K points nearest the origin via a max-heap on squared distance.
public class BranchLocatorService {
    private static final Logger log = Logger.getLogger(BranchLocatorService.class.getName());

    public List<int[]> kClosest(int[][] points, int k) {
        // max-heap: farthest (largest squared distance) at the root
        PriorityQueue<int[]> maxHeap = new PriorityQueue<>(
            (a, b) -> dist(b) - dist(a));
        for (int i = 0; i < k; i++) maxHeap.offer(points[i]);
        for (int i = k; i < points.length; i++) {
            if (dist(points[i]) < dist(maxHeap.peek())) {  // nearer than farthest kept
                maxHeap.poll();
                maxHeap.offer(points[i]);
            }
        }
        List<int[]> result = new ArrayList<>(maxHeap);
        log.info(() -> "Kept " + result.size() + " closest branches");
        return result;
    }

    private int dist(int[] p) { return p[0] * p[0] + p[1] * p[1]; } // squared distance
}
