package com.bank.branch;

import com.bank.branch.service.BranchLocatorService;
import java.util.Arrays;
import java.util.logging.Logger;

public class BranchLocatorApplication {
    private static final Logger log = Logger.getLogger(BranchLocatorApplication.class.getName());

    public static void main(String[] args) {
        BranchLocatorService service = new BranchLocatorService();
        int[][] branches = {{1, 3}, {-2, 2}, {5, 8}, {0, 1}};
        service.kClosest(branches, 2).forEach(p -> log.info("Closest branch: " + Arrays.toString(p)));
    }
}
